INSERT INTO quotation.quotationitem (no, versionId, type, quotationTypeId, quotationClassificationId, quotationBigCategoryId, quotationSmallCategoryId, name, measurementUnitId, workTypeId, comment, addPrice, unitPrice, subPrice, status, discount) VALUES
('QI_00000', 'QV_245', 0, 1, 1, 1, 12, '原墙棚大白铲除', 2, 7, '1.工艺：人工铲除墙、顶面饰面及腻子层并装袋。 2.乙供：垃圾袋、人工及机械。 3.说明：饰面包含普通乳胶漆；如墙面、顶面含造型，费用另计；如原墙顶粉刷石膏找平层存在开裂、起砂、空鼓等问题，则应铲除，费用另计；不包含耐水腻子铲除或可拆除保温层拆除等费用；垃圾排放到园区指定地点，如需外运费用另计。', 3500, 3500, 3500, 0, 1),
('QI_00001', 'QV_245', 0, 1, 1, 1, 12, '原墙棚仿瓷大白,耐水腻子铲除', 2, 7, '1.工艺：人工铲除墙、顶面涂料及耐水腻子层并装袋。 2.乙供：垃圾袋、人工及机械。 3.说明：饰面包含壁纸、壁布、仿瓷大白铲除；如原墙顶粉刷石膏找平层存在开裂、起砂、空鼓等问题，则应铲除，费用另计；不包括水泥砂浆层铲除或可拆除保温层拆除等费用；垃圾排放到园区指定地点，如需外运费用另计。', 10000, 10000, 10000, 0, 1),
('QI_00002', 'QV_245', 0, 1, 1, 1, 23, '阳台保温层拆除', 2, 1, '1.工艺：人工拆除室内保温层、并机械剔除墙面粘贴剂并装袋。 2.乙供：垃圾袋、人工及机械。 3.说明：垃圾排放到园区指定地点，如需外运费用另计。', 25000, 25000, 25000, 0, 1),
('QI_00003', 'QV_245', 0, 1, 1, 1, 23, '阳台墙砖铲除', 2, 1, '1.工艺：人工非保护性铲除瓷砖、马赛克及墙面水泥砂浆找平粘贴层（厚20mm以内）并装袋。 2.乙供：垃圾袋、人工及机械。 3.说明：垃圾排放到园区指定地点，如需外运费用另计。', 15000, 15000, 15000, 0, 1),
('QI_00004', 'QV_245', 0, 1, 1, 1, 12, '120mm以内墙体拆除', 2, 1, '1.工艺：人工拆除墙厚120mm以内各类砌块墙体并装袋。 2.乙供：垃圾袋、人工及机械。 3.说明：不包含混凝土墙（承重结构）拆除；砖混结构禁止拆除。垃圾排放到园区指定地点，如需外运费用另计。', 50000, 50000, 50000, 0, 0),
('QI_00005', 'QV_245', 0, 1, 1, 1, 12, '240mm以内墙体拆除', 2, 1, '1.工艺：人工拆除墙厚240mm以内各类砌块墙体并装袋。 2.乙供：垃圾袋、人工及机械。 3.说明：不包含混凝土墙（承重结构）拆除；砖混结构禁止拆除。垃圾排放到园区指定地点，如需外运费用另计。', 100000, 100000, 100000, 0, 0),
('QI_00006', 'QV_245', 0, 1, 1, 3, 1, '厨房排水立杠制作', 12, 2, '1.工艺：PVC排水管安装→管件连接。 2.乙供：PVC排水管、辅料、人工及机械。 3.说明：适用于厨房无下水管道或损坏严重重新制作；不含水钻打眼。', 600000, 600000, 600000, 0, 1),
('QI_00007', 'QV_245', 0, 1, 1, 3, 1, '厨房PVC排水立杠三通下落或上提', 12, 2, '1.工艺：原始三通切割→更换新三通下落至标准高度。 2.乙供：本子目需要的材料、人工及机械。 3.说明：适用于厨房下水立杠下沉或棚面支杠上提；不含水钻打眼。', 200000, 200000, 200000, 0, 1),
('QI_00008', 'QV_245', 0, 1, 1, 3, 1, '厨房铸铁排水立杠三通下落或上提', 12, 2, '1.工艺：原始三通切割→更换新三通下落至标准高度。 2.乙供：本子目需要的材料、人工及机械。 3.说明：适用于厨房下水立杠下沉或棚面支杠上提；不含水钻打眼。', 300000, 300000, 300000, 0, 1),
('QI_00009', 'QV_245', 0, 1, 1, 3, 1, '厨房排水管道隔音处理', 12, 2, '1.工艺：检查排水立杠检修口→清理管道表面→包隔音棉→扎带固定→锡纸包裹缝隙。 2.乙供：辅料、人工及机械。 3.说明：环形包裹处理，包扎严密无空隙。', 120000, 120000, 120000, 0, 1),
('QI_00010', 'QV_245', 0, 1, 1, 3, 1, '厨房地面排水管道支杠改造', 12, 2, '1.工艺：确定位置→通水测试→管道制作。 2.乙供：PVC排水管、辅料、人工及机械。 3.说明：厨房原始预留管道接至现有水槽和厨房其他用水部位。', 150000, 150000, 150000, 0, 1),
('QI_00011', 'QV_245', 0, 1, 1, 3, 1, '厨房地面排水管道支杠重新制作', 12, 2, '1.工艺：确定位置→PVC排水管安装→管件连接→通水测试。 2.乙供：PVC排水管、辅料、人工及机械。 3.说明：适用于厨房位置变更，独立西厨及独立洗衣间下水制作；不含水钻打孔。', 300000, 300000, 300000, 0, 1),
('QI_00012', 'QV_245', 0, 1, 1, 3, 1, '厨房棚面排水管道支杠改造', 12, 2, '1.工艺：确定位置→原始排水管道切割→PVC排水管安装→管件连接→通水测试。 2.乙供：PVC排水管、辅料、人工及机械。 3.说明：适用于厨房棚面支杠走向改造（躲避燃气热水器排烟管）。', 300000, 300000, 300000, 0, 1),
('QI_00013', 'QV_245', 0, 1, 1, 1, 1, '厨房洗菜槽安装', 12, 2, '1.工艺：确定位置→上下水连接安装。 2.乙供：防霉玻璃胶、人工及机械。 3.甲供：洗菜槽、水龙头、角阀、软连接、挂件。 4.说明：不含理石开孔；套餐包项目无单项费用退减；与配套卫生间卫浴产品、开关插座同时安装，如需单独安装费用另计（100元/趟）。', 80000, 80000, 80000, 0, 1),
('QI_00014', 'QV_245', 0, 1, 1, 3, 16, '卫生间PVC排风管道制作', 12, 2, '1.工艺：确定位置→PVC管道安装→管件连接→吊卡固定。 2.乙供：PVC排水管及辅料、人工及机械。 3.说明：适用于原卫生间无排风管道增加卫生间排风功能，室外部分甲方自理；不含水钻钻孔。', 280000, 280000, 280000, 0, 1),
('QI_00015', 'QV_245', 0, 1, 1, 3, 16, '卫生间排水立杠制作', 12, 2, '1.工艺：PVC排水管安装→管件连接 2.乙供：PVC排水管、辅料、人工及机械。 3.说明：适用于卫生间无下水管道或损坏严重重新制作；不含水钻打眼。', 700000, 700000, 700000, 0, 1),
