('QI_00089', 'QV_248', 0, 1, 3, 3, 15, '室外给水点位', 12, 2, '1.工艺：确定位置→PPR管道安装→管件连接→打压测试。 2.乙供：PPR给水管、辅料、人工及机械。 3.说明：如有两处及以上给水点位提供一处独立阀门控制；不含水钻钻孔。', 300000, 300000, 300000, 0, 0),
('QI_00090', 'QV_248', 0, 1, 1, 1, 5, '卫生间卫浴保护性拆除', 12, 2, '1.工艺：拆除并装袋。 2.乙供：垃圾袋、人工及机械。 3.说明：不含拆除后安装费用，不含拆浴屏；垃圾排放到园区指定地点，如需外运费用另计。', 300000, 300000, 300000, 0, 0),
('QI_00091', 'QV_248', 0, 1, 1, 1, 1, '进户阀门更换', 12, 2, '1.说明：原始进户入阀门更换', 200000, 200000, 200000, 0, 0),
('QI_00092', 'QV_248', 0, 1, 1, 1, 5, '水暖最低收费', 12, 2, '1.乙供：辅材、人工及机械。', 500000, 500000, 500000, 0, 0),
('QI_00093', 'QV_248', 0, 1, 1, 1, 13, '暖气安装后打压（面积≤150平）', 12, 2, '1.乙供：人工及机械。 2.说明：适用于原始暖气位置不移动的打压；每增加1个分水器增加1项。', 300000, 300000, 300000, 0, 0),
('QI_00094', 'QV_248', 0, 1, 1, 1, 5, '水表移位', 12, 2, '1.工艺：确定位置→PPR管道安装→管件连接→打压测试。 2.乙供：PPR给水管、辅料、人工及机械。 3.甲供：水表。 3.说明：施工位置2米以内。每增加1米，按100元/米计费。', 200000, 200000, 200000, 0, 0),
('QI_00095', 'QV_248', 0, 1, 3, 4, 9, '暖气拆改（原地改造）', 14, 2, '1.工艺：确定位置→暖气安装→管件连接→打压测试。 2.乙供：PPR给水管、辅料、人工及机械。 3.说明：不含活接、暖气、不含水钻钻孔。', 220000, 220000, 220000, 0, 0),
('QI_00096', 'QV_248', 0, 1, 3, 4, 9, '暖气拆改（移位改造）', 14, 2, '1.工艺：确定位置→暖气安装→管件连接→打压测试。 2.乙供：PPR给水管、辅料、人工及机械。 3.说明：不含活接、暖气、不含水钻钻孔。', 280000, 280000, 280000, 0, 0),
('QI_00097', 'QV_248', 0, 1, 3, 4, 9, '暖气管线更换', 1, 2, '1.工艺：确定位置→暖气安装→管件连接→打压测试。 2.乙供：PPR给水管、辅料、人工及机械。 3.说明：不含活接、暖气、不含水钻钻孔。', 68000, 68000, 68000, 0, 0),
('QI_00098', 'QV_248', 0, 1, 3, 4, 9, '暖气拆卸及重新安装人工费(原地不改不动)', 14, 2, '1.说明：人工及机械；保留暖气情况下，墙面大白处理及墙面瓷砖铺设需要把所有暖气拆卸及重新安装。', 180000, 180000, 180000, 0, 0),
('QI_00099', 'QV_248', 0, 1, 1, 1, 13, '套餐外单改部分水管（4分管）', 1, 2, '1.工艺：确定位置→管线安装→管件连接→打压测试。 2.乙供：PPR给水管、辅料、人工及机械。 3.说明：最低按4米收费320元，不足4米最低收费，则按照最低收费收取。', 80000, 80000, 80000, 0, 0);
INSERT INTO quotation.quotationitem (no, versionId, type, quotationTypeId, quotationClassificationId, quotationBigCategoryId, quotationSmallCategoryId, name, measurementUnitId, workTypeId, comment, addPrice, unitPrice, subPrice, status, discount) VALUES
('QI_00100', 'QV_248', 0, 1, 1, 1, 13, '套餐外单改部分水管（6分管）', 1, 2, '1.工艺：确定位置→管线安装→管件连接→打压测试。 2.乙供：PPR给水管、辅料、人工及机械。 3.说明：最低按3米收费300元，不足3米最低收费，则按照最低收费收取', 100000, 100000, 100000, 0, 0),
('QI_00101', 'QV_248', 0, 1, 1, 1, 13, '套餐外单改部分水管（1寸管）', 1, 2, '1.工艺：确定位置→管线安装→管件连接→打压测试。 2.乙供：PPR给水管、辅料、人工及机械。 3.说明：最低按3米收费360元，不足3米最低收费，则按照最低收费收取。', 120000, 120000, 120000, 0, 0),
('QI_00102', 'QV_248', 0, 1, 1, 1, 3, '地热打压', 12, 2, '1.乙供：人工及机械。 2.说明：每增加1个分水器增加1项。', 300000, 300000, 300000, 0, 0),
('QI_00103', 'QV_248', 0, 1, 3, 3, 4, '弱电全屋布线', 2, 3, '1.工艺：定位→PVC线管加工→线盒固定→管路敷设→穿弱电线→线路检测。 2.乙供：本子目中需要的基础材料、人工及机械。 3.说明：（1）本定额仅限于弱电箱到各功能空间弱电点位（网络、光纤、电话、有线电视）管路敷设及穿线；（2）不含一个弱电箱更换，（3）弱电箱移位会导致入户光纤、网络、电话、有线电视线日后无法更换或升级；（4）不含入户光纤、网络、电话、有线电视线更换；（5）监控、智能家居系统等布线，费用另计；不足40平，按40平计。', 7000, 7000, 7000, 0, 0),
('QI_00104', 'QV_248', 0, 1, 1, 3, 4, '增设弱电箱', 12, 3, '1.工艺：确定位置→开槽→固定多媒体信息箱→管道敷设→穿线→线路测试。 2.乙供：子目中包含的材料、人工及机械。 3.说明：（1）包含换箱、移位、增设（箱体规格300mm*400mm*100mm），箱内预留220V电源；（2）入户光纤、网络、有线电视、电话信号线、通讯组件及支架由甲方负责。', 300000, 300000, 300000, 0, 0),
('QI_00105', 'QV_248', 0, 1, 3, 3, 4, '智能开关加零线', 2, 3, '1.乙供：子目中包含的材料、人工及机械。 2.说明：仅限照明开关线盒内增加一根零线。', 10000, 10000, 10000, 0, 0),
('QI_00106', 'QV_248', 0, 1, 3, 3, 4, '强电改造（平层）', 2, 3, '1.工艺：原始线路通断测试→定位→PVC线管加工→线盒固定→管路敷设→穿ZR-BV电线→并线焊锡→绝缘保护→线路检测。 2.乙供：本子目中需要的基础材料、人工及机械。 3.说明：（1）本电路工程改造是基于房屋有原始线路基础上进行断点改造施工，如房屋无原始线路或原始线路不符合改造标准，需增加全屋换线项目；（2）空调、电热水器、厨房插座使用4平方BV线(不含原始线路),普通插座使用2.5平方BV线，磁吸灯、线性灯、筒灯灯吊棚内灯线可使用1.0护套线（与BV线不同品牌）；（3）卧室、客厅主灯布置双控线路,不含走廊等其它位置双控,如其它位置需双控,费用另计；（4）不包括入户配电箱移位、速热热水器、中央空调系统、智能家居系统、新风系统、室外电源，费用另计；不足40平，按40平计。', 47000, 47000, 47000, 0, 0),
('QI_00107', 'QV_248', 0, 1, 3, 3, 4, '强电改造（非平层）', 2, 3, '1.工艺：原始线路通断测试→定位→PVC线管加工→线盒固定→管路敷设→穿ZR-BV电线→并线焊锡→绝缘保护→线路检测。 2.乙供：本子目中需要的基础材料、人工及机械。 3.说明：（1）本电路工程改造是基于房屋有原始线路基础上进行断点改造施工，如房屋无原始线路或原始线路不符合改造标准，需增加全屋换线项目；（2）空调、电热水器、厨房插座使用4平方BV线(不含原始线路),普通插座使用2.5平方BV线，磁吸灯、线性灯、筒灯灯吊棚内灯线可使用1.0护套线（与BV线不同品牌）；（3）卧室、客厅、楼梯主灯布置双控线路,不含走廊等其它位置双控,如其它位置需双控,费用另计；（4）不包括入户配电箱移位、速热热水器、中央空调系统、智能家居系统、新风系统、室外电源、楼梯踏步灯，费用另计。', 50000, 50000, 50000, 0, 0),
('QI_00108', 'QV_248', 0, 1, 3, 3, 4, '增加原始布线', 2, 3, '1.工艺：原始线路拆除→原始线管或新做线管穿线。 2.乙供：本子目中需要的基础材料、人工及机械。 3.说明：（1）原始布线线径标准，厨房、卫生间、空调使用4平方BV线，普通插座及照明使用2.5平方BV线；（2）不包括入户配电箱、入户主线。', 35000, 35000, 35000, 0, 0),
('QI_00109', 'QV_248', 0, 1, 1, 3, 4, '单一空间电路改造', 12, 3, '1.工艺：原始线路通断测试→定位→PVC线管加工→线盒固定→管路敷设→穿ZR-BV电线→并线焊锡→绝缘保护→线路检测。 2.乙供：本子目中需要的基础材料、人工及机械。 3.说明：（1）本电路工程改造是基于房屋有原始线路基础上进行断点改造施工，如房屋无原始线路或原始线路不符合改造标准，需增加全屋换线项目；（2）原结构不能进行深度开槽位置使用护套线（指部分钢筋混凝土结构），顶面开槽布线长度不超过1.2米；（3）包含7个点位的改造，不含强电配电箱移位，不含弱电，超出此区域每个点位增加150元。', 700000, 700000, 700000, 0, 0),
('QI_00110', 'QV_248', 0, 1, 1, 3, 4, '单一点位电路改造', 12, 3, '1.工艺：原始线路通断测试→定位→PVC线管加工→线盒固定→管路敷设→穿ZR-BV电线→并线焊锡→绝缘保护→线路检测。 2.乙供：本子目中需要的基础材料、人工及机械。 3.说明：（1）本电路工程改造是基于房屋有原始线路基础上进行断点改造施工，如房屋无原始线路或原始线路不符合改造标准，需增加全屋换线项目；（2）最少3个点位的改造，不足3个点位按照最低标准150元/项收费；不含弱电。', 150000, 150000, 150000, 0, 0),
('QI_00111', 'QV_248', 0, 1, 3, 3, 4, '更换强电箱', 12, 3, '1.工艺：确定位置→开槽→电箱固定→管道敷设→穿线→焊锡→绝缘保护→空开连接。 2.乙供：子目中包含的材料、人工及机械。 3.说明：适用于断电改造更换配电箱（原位更换），不包含原始入户线或进入该电箱的主线；不含箱体,空气开关组件。', 480000, 480000, 480000, 0, 0),
('QI_00112', 'QV_248', 0, 1, 3, 3, 4, '独立配电回路敷设', 12, 3, '1.工艺：放线定位→开槽→管线敷设→穿4平方BV线→绝缘保护→线路测试。 2.乙供：4平方BV线、辅材、人工及机械。 3.说明：仅限单独回路控制，如需多条单独回路依次累计增加此项。', 200000, 200000, 200000, 0, 0),
('QI_00113', 'QV_248', 0, 1, 3, 3, 4, '增加双控开关电路敷设', 5, 3, '1.工艺：卧室、客厅、楼梯主灯布置双控线路以外区域增加双控开关电路敷设的材料及人工费。 2.乙供：2.5平方BV线、辅料、人工及机械。 3.说明：不含开关。', 200000, 200000, 200000, 0, 0),
