('QI_00115', 'QV_248', 0, 1, 1, 3, 4, '增加4平方BV线敷设', 1, 3, '1.乙供：4平方BV线、辅材、人工及机械。 2.说明：适用于新风等设备布线。', 50000, 50000, 50000, 0, 0),
('QI_00116', 'QV_248', 0, 1, 1, 3, 4, '增加6平方BV线敷设', 1, 3, '1.乙供：6平方BV线、辅材、人工及机械。 2.说明：适用于速热电热水器、老房改造入户线。', 60000, 60000, 60000, 0, 0),
('QI_00117', 'QV_248', 0, 1, 3, 3, 4, '增加10平方BV线敷设', 1, 3, '1.乙供：10平方BV线、辅材、人工及机械。 2.说明：适用于新、老房改造入户线。', 68000, 68000, 68000, 0, 0),
('QI_00118', 'QV_248', 0, 1, 1, 1, 2, '灯具及开关插座安装（全翻必收）', 2, 3, '1.工艺：全屋灯具及开关插座安装及运行检查。 2.乙供：辅料、人工及机械。 3.甲供：灯具、开关、插座及配件。 4.说明：不含智能开关安装及调试、水晶灯、欧式吊灯等高档灯具安装，不足40平按40平计。', 4000, 4000, 4000, 0, 0),
