('QI_00177', 'QV_248', 0, 1, 1, 1, 12, '暗藏踢脚线开槽', 1, 1, '1.工艺：定位放线→无齿锯切割→剔槽→线槽清理→垃圾清理。 2.乙供：垃圾袋、人工及机械。 3.说明：垃圾排放到园区指定地点，如需外运费用另计。', 15000, 15000, 15000, 0, 0),
('QI_00178', 'QV_248', 0, 1, 1, 1, 12, '瓷砖或理石踢脚线铺设', 1, 4, '1.工艺：瓷砖或理石背面清理→踢脚清理→材料预排→标高定位→水泥砂浆搅拌→铺贴踢脚湿润→摊铺粘结层（厚度不超过20mm）→按定位线铺贴踢脚线→擦缝→油工处理边角→养护。 2.乙供：水泥、沙子、人工及机械。 3.甲供：瓷砖或理石踢脚线、定位卡（调平器）。 4.说明：不含瓷砖或理石加工费。', 35000, 35000, 35000, 0, 0),
('QI_00179', 'QV_248', 0, 1, 1, 1, 12, '嵌入式金属踢脚线', 1, 5, '1.工艺：踢脚清理→材料预排→标高定位→石膏U型槽制作→踢脚线安装。 2.乙供：石膏、人工及机械。 3.甲供：金属踢脚线。', 50000, 50000, 50000, 0, 0),
