-- ============================== 版本 QV_245 (386 项, 原有0行纯导入) ==============================
-- 防御性清空(新版本首次执行为0行; 脚本级幂等重跑)
DELETE qp FROM quotation.quotationprice qp, quotation.quotationitem qi WHERE qp.qiid = qi.qiid AND qi.versionId = 'QV_245';
DELETE FROM quotation.quotationitem WHERE versionId = 'QV_245';





-- QV_245 尾部: offset回写 / qvid回填 / quotationprice重建(镜像quotationItemImport.py)
UPDATE quotation.quotationversion qv SET qv.offset = (SELECT MAX(qiid) FROM quotation.quotationitem WHERE versionId = 'QV_245') WHERE qv.no = 'QV_245';
UPDATE quotation.quotationitem qi, quotation.quotationversion qv SET qi.qvid = qv.qvid WHERE qi.versionId = 'QV_245' AND qi.qvid IS NULL;

